package com.logatron.auth.dev;
import com.logatron.auth.persistence.*;import com.logatron.common.error.*;import org.springframework.context.annotation.Profile;import org.springframework.http.HttpStatus;import org.springframework.security.oauth2.jwt.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service @Profile("dev-auth") public class DevTokenService{private static final List<String> ALLOWED=List.of("admin","developer","project-admin","support");private final UserAccountRepository users;private final JwtEncoder encoder;private final DevAuthProperties properties;public DevTokenService(UserAccountRepository users,JwtEncoder encoder,DevAuthProperties properties){this.users=users;this.encoder=encoder;this.properties=properties;}public List<String> users(){return ALLOWED;}public DevTokenController.TokenResponse token(String username){if(!ALLOWED.contains(username))throw new ApiException(HttpStatus.BAD_REQUEST,ErrorCode.INVALID_REQUEST,"Unknown development identity.");var user=users.findByIssuerAndUsername(properties.issuer(),username).orElseThrow(ApiException::notFound);Instant now=Instant.now();var claims=JwtClaimsSet.builder().issuer(properties.issuer()).subject(user.getSubject()).audience(List.of(properties.audience())).issuedAt(now).expiresAt(now.plus(Duration.ofMinutes(properties.tokenMinutes()))).claim("preferred_username",user.getUsername()).claim("name",user.getDisplayName()).build();String token=encoder.encode(JwtEncoderParameters.from(JwsHeader.with(org.springframework.security.oauth2.jose.jws.MacAlgorithm.HS256).build(),claims)).getTokenValue();return new DevTokenController.TokenResponse(token,"Bearer",properties.tokenMinutes()*60);}}
